import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"RGW Zipper","description":"","frontmatter":{"title":"RGW Zipper","date":"2022-11-15T00:00:00.000Z","updated":"2022-11-16T00:00:00.000Z","tags":["Ceph","分布式存储","RGW","S3 API","存储集成"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/RGW_Zipper.md","filePath":"posts/2022/RGW_Zipper.md","lastUpdated":1780459816000}'),i={name:"posts/2022/RGW_Zipper.md"};function o(s,a,n,p,h,u){return t(),r("div",null,[...a[0]||(a[0]=[l('<h3 id="会议纪要-项目-zipper-讨论" tabindex="-1">会议纪要：项目 Zipper 讨论 <a class="header-anchor" href="#会议纪要-项目-zipper-讨论" aria-label="Permalink to &quot;会议纪要：项目 Zipper 讨论&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ul><li><strong>项目名称</strong>：Zipper</li><li><strong>目的</strong>：将 Ceph 的 RGW（RADOS Gateway）中的 S3 实现与其他存储系统（如 ISP 存储源或云存储）集成，通过灵活的 API 框架支持堆叠过滤器实现分层或缓存等功能。</li><li><strong>技术方法</strong>：通过解耦 RGW 的协议层与存储层，开发一个横跨 RGW 的 API（称为 Zipper API），以便插入其他存储插件。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题： <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题：&quot;">​</a></h4><ul><li><strong>架构设计</strong>： <ul><li>协议层、核心层和存储层的三层架构设计。</li><li>存储插件和过滤器通过 Zipper API 实现功能。</li></ul></li><li><strong>插件和过滤器</strong>： <ul><li>插件可以是内建或外建的，通过可加载的库实现。</li><li>过滤器通过默认实现传递未覆盖的部分。</li></ul></li></ul><h4 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h4><ul><li><strong>API 实现</strong>：提供一组纯虚拟基类，涵盖对象存储操作所需的各种概念。</li><li><strong>插件管理</strong>：插件支持在运行时加载。</li><li><strong>配置管理</strong>：使用 JSON 文档进行配置，确保集群中的每个 RGW 实例都能访问相同的配置信息。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>完成插件工作</strong>：预计在一个月内完成可加载插件的工作。</li><li><strong>开发 Lua 过滤器</strong>：计划开发一个 Lua 过滤器，允许通过脚本快速开发过滤器功能。</li></ul><h4 id="其他信息" tabindex="-1">其他信息： <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息：&quot;">​</a></h4><ul><li><strong>当前状态</strong>：Zipper 已被 Seagate、Intel 和 SUSE 等公司采用，并已成功集成到他们的系统中。</li><li><strong>技术限制</strong>：目前没有计划将 Zipper 从 C++ 解耦，但未来可能会有变化。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议主持人感谢大家的参与，并邀请大家在会后通过电子邮件或 Google Chat 提出任何问题。</li></ul>',13)])])}const c=e(i,[["render",o]]);export{g as __pageData,c as default};
